import json,pathlib,csv,collections,hashlib,os
ROOT=pathlib.Path(__file__).parent
from metrics import ARMS,read

def response(c,arm):
 r=read(ROOT/'runs/test'/ARMS[arm]/(c['id']+'.json'));parts=[f"**{arm} — `{r['status']}`:**"]
 for x in r.get('claims',[]):parts.append('> '+x['text'].replace('\n','\n> ')+'\n>\n> Источники: '+', '.join(x['doc_ids']))
 if not r.get('claims'):parts.append('> Подтверждённый текст ответа не выдан.')
 if r.get('actions'):parts.append('Структурированные actions: `'+json.dumps(r['actions'],ensure_ascii=False)+'`')
 return '\n\n'.join(parts)

def table(items,fields):
 lines=['| '+ ' | '.join(fields)+' |','|'+ '|'.join(['---']*len(fields))+'|']
 for x in items:lines.append('| '+' | '.join(str(x.get(f,'')) for f in fields)+' |')
 return '\n'.join(lines)

