 repair=read(ROOT/'context_repair_study.json');statuses=[{'Конфигурация':a,'Исходный контекст':read(ROOT/'runs/test'/ARMS[a]/(repair['original_case']['id']+'.json'))['status'],'С сохранённым заголовком':r['status']} for a,r in repair['results'].items()]
 sections.append('## Потеря отрицания при подготовке контекста\n\nВ MD-примере `97b89d77600b3661ce5a2942127643cb-9` span 7 — реальный заголовок **Do not**. У spans 8–10 title также **Do not**. Подготовка v1 использовала только text_sec и потеряла отрицание. Это ошибка подготовки данного эксперимента: структура была доступна в исходных данных. Исходные входы и результаты не переписаны. Новый helper structured_context.py сохраняет настоящие title/parent_titles.\n\nНиже отдельный незаслеплённый case study; его нельзя подмешивать в исходный benchmark или оценивать по ошибочному положительному эталону.\n\n'+table(statuses,['Конфигурация','Исходный контекст','С сохранённым заголовком'])+'\n\nПолные новые ответы, точный исправленный контекст и запросы — context_repair_study.json.')
 taxonomy=[('Неподтверждённый факт','L95…: A4 приписывает двум хуторам чужую численность.'),('Неверный источник','L95…: источник о Ремизове привязан к утверждению о Косовском.'),('Пропущенный шаг','816…: A0 пропускает возврат выплат.'),('Лишнее/изменённое действие','c517…: A4 меняет apply на обязательное получение COE.'),('Потерянное условие','261…: A2/A4 опускают первоначальный запрос SSN.'),('Неправильный порядок','Надёжная разметка обязательного порядка отсутствует; глобальный показатель не измерен.'),('Ложный отказ','816… сравнивается по полноте; конкретные good-отказы и их метки полностью в per_case_metrics.csv. Метка good не гарантирует достаточность: Ke8… — контрпример.'),('Ответ без нужной информации','LtW… и TR98…: OOD-ответы; полный текст в runs/test. Релевантный сопутствующий факт не отвечает на отсутствующую часть вопроса.'),('Неудачное объединение документов','L95…: перестановка сущностей между двумя источниками.'),('Ошибка формата/контракта','A0 dev Vrv…: JSON мог соответствовать схеме, но конфликт ссылался на один документ. Отдельный diagnostic replay, не восстановленный оригинальный HTTP-пакет.'),('Превышение времени','Считать по фактическим ошибкам в result.error; отсутствие таймаута не доказывает предел задержки на длинном контексте.'),('Ошибка контекста','MD 97…: потерян реальный заголовок отрицания. Long-context отказы judge отражены отдельно и не названы ошибками генератора.')]
 (ROOT/'error_analysis.md').write_text('# Анализ реальных ответов\n\nПримеры выбраны после просмотра результатов для объяснения ошибок. Это качественный разбор, не случайная независимая человеческая выборка. Полные входы/эталоны и ответы сохранены без подмены.\n\n'+'\n\n'.join(sections)+'\n\n## Таксономия\n\n'+table([{'Тип':a,'Наблюдение':b} for a,b in taxonomy],['Тип','Наблюдение'])+'\n',encoding='utf8')
